function renderRuleTemplates(){const root=$('#ruleTemplateList');root.replaceChildren();$('#saveRuleTemplate').disabled=ruleTemplates.length>=maximumRuleTemplates;if(ruleTemplates.length===0){const empty=document.createElement('div');empty.className='rule-template-empty';empty.textContent=raceI18n.isEnglish?'No rule templates saved':'尚未保存规则模板';root.append(empty);return;}for(const template of ruleTemplates){const card=document.createElement('article');card.className='rule-template-card';const copy=document.createElement('div');copy.className='rule-template-card-copy';const title=document.createElement('div');title.className='rule-template-card-title';const name=document.createElement('strong');name.textContent=template.name;const time=document.createElement('time');time.dateTime=template.updatedAt;time.textContent=new Date(template.updatedAt).toLocaleDateString(raceLocale);title.append(name,time);const summary=document.createElement('p');summary.className='rule-template-card-summary';summary.textContent=ruleTemplateSummary(template.rules);copy.append(title,summary);const actions=document.createElement('div');actions.className='rule-template-card-actions';const apply=actionButton(raceI18n.isEnglish?'Apply':'应用',()=>applyRuleTemplate(template));apply.className='apply';const update=actionButton(raceI18n.isEnglish?'Overwrite':'用当前设置覆盖',()=>updateRuleTemplate(template));const remove=actionButton(raceI18n.isEnglish?'Delete':'删除',()=>removeRuleTemplate(template));remove.className='danger';actions.append(apply,update,remove);card.append(copy,actions);root.append(card);}}
