async function saveSettings(){const allowTeams=$('#allowTeams').checked,teams=allowTeams?readTeamRows():[];const indicator=$('#settingsSaved');if(allowTeams&&teams.some(team=>!team.name)){indicator.textContent='每支车队都要填写名字';indicator.className='save-state error';return;}const body={sessionName:value('#sessionName'),totalRaceLaps:numberValue('#raceLaps'),minimumRequiredPitStops:numberValue('#minimumRequiredPitStops'),sectorCount:numberValue('#sectorCount'),automaticYellowEnabled:$('#automaticYellow').checked,automaticCollisionInvestigationsEnabled:$('#automaticCollisionInvestigations').checked,disconnectedLapRecoveryEnabled:$('#disconnectedLapRecovery').checked,slowSpeedKph:numberValue('#slowSpeedKph'),slowDurationSeconds:numberValue('#slowDurationSeconds'),severeLateralOffsetMeters:numberValue('#severeLateralOffsetMeters'),recoveryDurationSeconds:numberValue('#recoveryDurationSeconds'),trackLimitMode:value('#trackLimitMode')||'warningsOnly',allowTeams,trackName:value('#trackName')||null,trackId:value('#trackId')||null,trackRevision:activeTrackRevision,trackPackageHash:value('#trackPackageHash')||null,teamCount:allowTeams?teams.length:Math.max(1,numberValue('#teamCount')),driversPerTeam:Math.max(1,numberValue('#driversPerTeam')),teams};const response=await request('/api/admin/settings',body);if(!response.ok){indicator.textContent=(await safeJson(response))?.error??'保存失败';indicator.className='save-state error';return;}teamDraft=teams;indicator.textContent='已保存';indicator.className='save-state success';rebuildSectorOptions(body.sectorCount);setTimeout(()=>indicator.textContent='',2500);await refresh();await loadTrackPackageStatus();}
