function togglePracticeSettings(){const count=Math.min(3,Math.max(1,numberValue('#practiceSessionCount')||1));$('#practiceFP2MinutesField').classList.toggle('hidden',count<2);$('#practiceFP3MinutesField').classList.toggle('hidden',count<3);updateSessionControls(lastState);}
function toggleQualifyingSettings(){const count=Math.min(3,Math.max(1,numberValue('#qualifyingSessionCount')||1));$('#singleQualifyingSettings').classList.toggle('hidden',count!==1);$('#multiQualifyingSettings').classList.toggle('hidden',count===1);$('#qualifyingQ3MinutesField').classList.toggle('hidden',count<3);$('#qualifyingQ2EliminationsField').classList.toggle('hidden',count<3);updateQualifyingRuleHint();updateSessionControls(lastState);}
function updateSessionControls(state){
  const practiceButton=$('[data-session="practice"]'),qualifyingButton=$('[data-session="qualifying"]');
  const practiceCount=Math.min(3,Math.max(1,numberValue('#practiceSessionCount')||1));
  const qualifyingCount=Math.min(3,Math.max(1,numberValue('#qualifyingSessionCount')||1));
  practiceButton.disabled=false;qualifyingButton.disabled=false;
  practiceButton.textContent=practiceCount>1?'开始 FP1':'开始练习赛';
  qualifyingButton.textContent=qualifyingCount>1?'开始 Q1':'开始排位';
  if(!state)return;
  if(state.phase==='practice'){
    const current=state.practiceSessionNumber??1,total=state.practiceSessionCount??1;
    if(state.practiceTimeExpired&&state.practiceEndsAt===null&&current<total)practiceButton.textContent=`开始 FP${current+1}`;
    else if(state.practiceTimeExpired&&state.practiceEndsAt===null){practiceButton.textContent=`${total>1?`FP${current}`:'练习赛'} 已结束`;practiceButton.disabled=true;}
    else{practiceButton.textContent=state.practiceTimeExpired?`等待 FP${current} 收尾圈`:`FP${current} 进行中`;practiceButton.disabled=true;}
  }
  if(state.phase==='qualifying'){
    const current=state.qualifyingSessionNumber??1,total=state.qualifyingSessionCount??1;
    if(state.qualifyingTimeExpired&&state.qualifyingEndsAt===null&&current<total)qualifyingButton.textContent=`开始 Q${current+1}`;
    else{qualifyingButton.textContent=state.qualifyingTimeExpired?`等待 Q${current} 收尾圈`:`Q${current} 进行中`;qualifyingButton.disabled=true;}
  }
}
function defaultQualifyingEliminations(participants,sessions){const total=Math.min(12,Math.max(0,participants)),count=Math.min(3,Math.max(1,sessions));if(count===1||total<=1)return Array.from({length:count-1},()=>0);if(count===2)return[Math.max(0,total-Math.max(1,Math.ceil(total/2)))];const finalists=Math.max(2,Math.ceil(total/2)),eliminated=Math.max(0,total-finalists),q1=Math.ceil(eliminated/2);return[q1,eliminated-q1];}
function updateQualifyingRuleHint(){const count=Math.min(3,Math.max(1,numberValue('#qualifyingSessionCount')||1)),participants=lastState?.participants?.filter(item=>item.isConnected).length??0,hint=$('#qualifyingRuleHint');if(count===1){hint.textContent='单节排位沿用原有规则，不执行淘汰。';return;}const defaults=defaultQualifyingEliminations(participants,count),q1=optionalNumber('#qualifyingQ1Eliminations')??defaults[0]??0,q2=count===3?(optionalNumber('#qualifyingQ2Eliminations')??defaults[1]??0):0;hint.innerHTML=raceI18n.isEnglish?`<strong>${participants}</strong> drivers online: <strong>${q1}</strong> eliminated in Q1${count===3?`, <strong>${q2}</strong> eliminated in Q2`:''}. Leave blank to use the calculated values.`:`当前 <strong>${participants}</strong> 名在线车手：Q1 淘汰 <strong>${q1}</strong> 人${count===3?`，Q2 淘汰 <strong>${q2}</strong> 人`:''}。留空即使用默认值。`;}

