  const qualifyingLabel=(state.qualifyingSessionCount??1)>1?`Q${state.qualifyingSessionNumber}/${state.qualifyingSessionCount}`:'排位赛';
  const activeLabel=practice?practiceLabel:qualifying?qualifyingLabel:phaseLabels[activePhase]??activePhase;
  const phaseLabel=state.phase==='suspended'?`比赛暂停 · ${activeLabel}`:practice&&state.practiceSessionCount>1?`练习赛 ${practiceLabel}`:qualifying&&state.qualifyingSessionCount>1?`排位赛 ${qualifyingLabel}`:phaseLabels[state.phase]??state.phase;
