  const displayedFlag=state.chequeredImminent&&state.flag==='green'?'chequered':state.flag,flagCard=$('#flagCard');
  flagCard.className=`panel summary-card flag-card ${displayedFlag}`;
  text('#flagValue',state.chequeredImminent&&state.flag==='green'?'CHEQUERED SOON':flagLabels[state.flag]??state.flag.toUpperCase());
  text('#flagMessage',state.chequeredImminent&&state.flag==='green'?'领跑者即将完成预定圈数':state.flagMessage||(state.flag==='green'?'赛道正常':'等待说明'));
