  text('#onlineValue',online);text('#readyValue',`${ready} 人已准备`);text('#fastestValue',formatTime(state.fastestLapSeconds));
  const fastest=state.participants.find(item=>item.id===state.fastestParticipantId);text('#fastestDriver',fastest?.displayName??'尚无有效圈');
