function participantStatusText(participant){if(participant.qualifyingEliminatedInSession)return`Q${participant.qualifyingEliminatedInSession} 淘汰`;if(participant.isServingTimePenalty)return`执行罚时 ${(participant.penaltyServiceElapsedSeconds??0).toFixed(1)} / ${(participant.penaltyServiceRequiredSeconds??0).toFixed(0)} 秒`;if(participant.isServingDriveThrough)return'正在执行通过维修区';if(participant.hasPendingDriveThrough){if(participant.driveThroughOverdue||(participant.driveThroughLapsRemaining??0)<=0)return'通过维修区 · 本圈必须执行';return`通过维修区 · 还可过线 ${participant.driveThroughLapsRemaining} 次`;}if((participant.pendingTimePenaltySeconds??0)>0)return`待执行 +${participant.pendingTimePenaltySeconds.toFixed(0)} 秒`;if(participant.isInServiceZone){if(participant.pitServiceRequirementMet)return`维修停留完成 · ${participant.completedPitServices} 次`;if(participant.pitServiceElapsedSeconds>0)return`维修停留 ${participant.pitServiceElapsedSeconds.toFixed(1)} 秒`;}return statusLabels[participant.status]??participant.status;}
function renderEvents(events){eventRows.replaceChildren();if(!Array.isArray(events)||events.length===0){const empty=document.createElement('div');empty.className='event-empty';empty.textContent='尚无赛事事件';eventRows.append(empty);return;}for(const event of events){const item=document.createElement('article');item.className=`event-row event-${event.type}`;const occurredAt=event.occurredAt??event.at;const time=document.createElement('time');time.dateTime=occurredAt;time.textContent=new Date(occurredAt).toLocaleTimeString(raceLocale,{hour12:false});const type=document.createElement('strong');type.textContent=eventTypeText(event.type);const message=document.createElement('span');message.textContent=event.message;item.append(time,type,message);eventRows.append(item);}}
function eventTypeText(type){const labels={participantJoined:'加入',participantDisconnected:'离开',participantRemoved:'总控断开',observerJoined:'OB 加入',observerResumed:'OB 重连',observerDisconnected:'OB 离开',observerRemoved:'总控断开 OB',readyChanged:'准备',sessionChanged:'流程',flagChanged:'旗语',automaticYellow:'自动黄旗',automaticYellowCleared:'恢复绿旗',lapCompleted:'圈速',lapCompletedNotFastest:'无最快资格',lapInvalid:'无效圈',trackLimitWarning:'边界警告',automaticPenalty:'自动判罚',manualPenalty:'人工判罚',falseStart:'抢跑',pitEntered:'进站',pitBoxEntered:'进入换胎区',pitServiceCompleted:'换胎完成',pitServiceCompletedRecovered:'换胎补传',minimumPitStopsNotMet:'进站未达标',minimumPitStopsRecovered:'进站已恢复',pitExited:'出站',penaltyServiceStarted:'执行罚时',penaltyServiceCompleted:'罚时完成',penaltyServiceFailed:'罚时失败',driveThroughServed:'通过维修区完成',driveThroughOverdue:'完赛加时',investigationOpened:'开始调查',collisionInvestigationOpened:'碰撞调查',collisionInvestigationSetting:'碰撞检测',investigationPenalized:'调查判罚',investigationDismissed:'结束调查',penaltyUpdated:'修改判罚',penaltyRevoked:'取消判罚',chequeredFlag:'方格旗',raceStarted:'发车',qualifyingExpired:'排位结束',participantStatus:'车手状态',roomSettings:'房间设置'};return labels[type]??type;}
function actionsCell(participant){const td=document.createElement('td'),wrap=document.createElement('div');wrap.className='actions';const timePicker=document.createElement('span'),seconds=document.createElement('select');timePicker.className='time-penalty-picker';Object.assign(timePicker.style,{display:'inline-flex',alignItems:'center',gap:'4px'});Object.assign(seconds.style,{width:'68px',minHeight:'30px',height:'30px',padding:'0 5px',fontSize:'10px'});seconds.title='选择手动罚时秒数';seconds.setAttribute('aria-label',`选择对 ${participant.displayName} 的罚时秒数`);for(let value=1;value<=6;value++)seconds.append(new Option(`+${value} 秒`,String(value)));seconds.value=String(penaltySecondsByParticipant.get(participant.id)??5);const holdTimingRefresh=()=>timingInteractionUntil=Date.now()+30000;seconds.addEventListener('focus',holdTimingRefresh);seconds.addEventListener('pointerdown',holdTimingRefresh);seconds.addEventListener('change',()=>{penaltySecondsByParticipant.set(participant.id,Number.parseInt(seconds.value,10));timingInteractionUntil=Date.now()+350;});seconds.addEventListener('blur',()=>timingInteractionUntil=Date.now()+100);timePicker.append(seconds,actionButton('罚时',()=>penalty(participant,'time',penaltySecondsByParticipant.get(participant.id)??Number.parseInt(seconds.value,10))));wrap.append(actionButton('警告',()=>penalty(participant,'warning')),timePicker,actionButton('通过维修区',()=>penalty(participant,'driveThrough')));if(canManageRace())wrap.append(actionButton('退赛',()=>participantStatus(participant,'didNotFinish')));wrap.append(actionButton('取消资格',()=>penalty(participant,'disqualification')));if(canManageRace()){const disconnect=actionButton('断开',()=>disconnectClient(participant));disconnect.className='disconnect-client';wrap.append(disconnect);}td.append(wrap);return td;}
