async function loadTrackPackageStatus(){const status=$('#trackPackageStatus');try{const response=await fetch('/api/admin/track-package',{cache:'no-store'});if(!response.ok){status.textContent='无法读取托管状态';status.className='track-package-status error';return;}const body=await response.json(),hosted=body.package;if(!hosted){status.textContent=`尚未托管赛道文件 · 上限 ${(body.maximumBytes/1048576).toFixed(1)} MiB`;status.className='track-package-status';return;}const matches=value('#trackId').toLowerCase()===hosted.trackId.toLowerCase()&&value('#trackPackageHash').toLowerCase()===hosted.trackPackageHash.toLowerCase();status.textContent=`${hosted.fileName} · ${(hosted.sizeBytes/1024).toFixed(1)} KiB · ${matches?'已与当前房间赛道匹配':'与当前房间填写信息不匹配，客户端不会收到下载入口'}`;status.className=`track-package-status ${matches?'ready':'error'}`;}catch{status.textContent='无法读取托管状态';status.className='track-package-status error';}}
