async function loadOrganizerLogoStatus(){const status=$('#organizerLogoStatus'),preview=$('#organizerLogoPreview');try{const response=await fetch('/api/admin/organizer-logo',{cache:'no-store'});if(!response.ok)throw new Error();const body=await response.json(),logo=body.logo;preview.classList.toggle('visible',Boolean(logo));preview.src=logo?`/api/organizer-logo?v=${encodeURIComponent(logo.sha256)}`:'';status.textContent=logo?`${logo.fileName} · ${(logo.sizeBytes/1024).toFixed(1)} KiB · 已同步给客户端`:`正在使用默认 LF Logo · 上传上限 ${(body.maximumBytes/1024).toFixed(0)} KiB`;status.className='track-package-status ready';}catch{preview.classList.remove('visible');status.textContent='无法读取 Logo 状态';status.className='track-package-status error';}}
